  "items": [
    {
      "id": "R1",
      "type": "PROCESS",
      "otherName": "",
      "reason": "전사 이후 세포질 이동이 이어지는 단계의 차례를 제시하므로 과정·순서이다."
    },
    {
      "id": "R2",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포질로 이동한 다음 리보솜에서 단백질이 합성되는 순서를 제시하므로 과정·순서이다."
    },
    {
      "id": "R3",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "일반적인 mRNA 매개 단백질 합성 원리를 바이러스의 숙주 세포 이용에 가져다 쓰므로 원리 적용이다."
    },
    {
      "id": "R4",
      "type": "CAUSE",
      "otherName": "",
      "reason": "바이러스 단백질의 합성이 생물체의 항원 인식을 유발하는 실제 생물학적 작용으로 이어지므로 인과·작용이다."
    },
    {
      "id": "R5",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "바이러스에 대한 면역 반응 원리를 인공적인 백신 접종에 활용하므로 원리 적용이다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "백신의 면역 유도 방식을 그 한 사례인 mRNA 백신의 작동 방식으로 자세히 풀므로 구체화·예시이다."
    },
    {
      "id": "R7",
      "type": "CAUSE",
      "otherName": "",
      "reason": "합성된 바이러스 단백질이 실제로 면역 반응을 유도하므로 인과·작용이다."
    },
    {
      "id": "R8",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "기존 백신과 mRNA 백신을 접종 물질이 바이러스인지라는 같은 기준으로 비교하므로 대조이다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "바이러스가 아니라는 사실을 근거로 백신에 의한 바이러스 감염 위험이 없다고 판단하므로 근거·도출이다."
    },
    {
      "id": "R10",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "체내 효소에 쉽게 분해된다는 성질을 체내에서 불안정하다는 말로 다시 표현하므로 재진술에 해당한다."
    },
    {
      "id": "R11",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 mRNA 백신의 장점을 인정하면서 불안정성과 낮은 흡수율이라는 한계를 제시하므로 양보·한계이다."
    },
    {
      "id": "R12",
      "type": "CAUSE",
      "otherName": "",
      "reason": "큰 분자 크기가 실제로 mRNA의 세포 흡수를 어렵게 만드는 요인으로 제시되므로 인과·작용이다."
    },
    {
      "id": "R13",
      "type": "CAUSE",
      "otherName": "",
      "reason": "mRNA의 음전하가 세포막과의 반발을 통해 세포 흡수를 방해하는 실제 요인이므로 인과·작용이다."
    },
    {
      "id": "R14",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "mRNA의 불안정성과 낮은 세포 흡수율이라는 문제에 지질 나노 입자 이용으로 대응하므로 문제·대응이다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "지방산으로 이루어졌다는 구성상의 사실을 근거로 지질의 소수성을 설명하므로 근거·도출이다."
    },
    {
      "id": "R16",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "물질의 혼합 원리를 지질이 물과 섞이지 않는다는 설명의 근거로 제시하므로 근거·도출이다."
    },
    {
      "id": "R17",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "친수성 물질과 소수성 물질을 어떤 물질과 섞이는지라는 같은 기준에서 비교하므로 대조이다."
    },
    {
      "id": "R18",
      "type": "CAUSE",
      "otherName": "",
      "reason": "인지질의 양친매성이 실제 세포막 배열과 그에 따른 투과 차단으로 이어지므로 인과·작용이다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "소수성 꼬리가 모인 세포막 구조가 친수성 물질의 투과를 실제로 차단하므로 인과·작용이다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "지질 나노 입자의 이용을 양이온성 지질의 구체적인 작동 방식으로 풀어 설명하므로 구체화·예시이다."
    },
    {
      "id": "R21",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "인지질 인산기 머리의 음전하라는 동일한 내용을 세포막 설명에서 다시 말하므로 재진술에 해당한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인산기 머리와 반발하지 않는다는 사실로 양이온성 지질의 반발력 방지 효과를 뒷받침하므로 근거·도출이다."
    },
    {
      "id": "R23",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 양이온성 지질이 실험실에서는 효과가 있지만 체내에서는 제한된다는 한계를 제시하므로 양보·한계이다."
    },
    {
      "id": "R24",
      "type": "CAUSE",
      "otherName": "",
      "reason": "혈장 단백질의 흡착이 실제로 mRNA의 세포막 투과를 제한하므로 인과·작용이다."
    },
    {
      "id": "R25",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "양이온성 지질의 체내 투과 제한 문제를 보완하기 위해 이온화 지질을 사용하므로 문제·대응이다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "높은 수소 이온 농도가 실제로 이온화 지질의 양이온화를 일으키므로 인과·작용이다."
    },
    {
      "id": "R27",
      "type": "CAUSE",
      "otherName": "",
      "reason": "수소 이온을 적게 받아들이는 현상이 이온화 지질의 전기적 중성화로 이어지므로 인과·작용이다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "이온화 지질의 전기적 중성화가 혈장 단백질의 흡착을 막는 실제 작용으로 제시되므로 인과·작용이다."
    },
    {
      "id": "R29",
      "type": "CONDITION",
      "otherName": "",
      "reason": "용액의 pH가 낮은 경우와 높은 경우에 따라 이온화 지질의 전하 상태가 갈리므로 조건·분기이다."
    },
    {
      "id": "R30",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "pH에 따른 전하 변화 원리를 중성 mRNA-지질 나노 입자 복합체의 제조에 활용하므로 원리 적용이다."
    },
    {
      "id": "R31",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "양이온성 지질과 중성 이온화 지질을 혈장 단백질의 흡착 여부라는 같은 기준에서 비교하므로 대조이다."
    },
    {
      "id": "R32",
      "type": "PROCESS",
      "otherName": "",
      "reason": "낮은 pH에서 결합시킨 다음 pH를 높이는 제조 단계의 차례를 연결하므로 과정·순서이다."
    },
    {
      "id": "R33",
      "type": "PROCESS",
      "otherName": "",
      "reason": "복합체 제조 이후 수용체 결합과 내포 작용에 의한 세포 진입이 이어지는 단계적 흐름이므로 과정·순서이다."
    },
    {
      "id": "R34",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "복합체의 진입 방식으로 제시된 내포 작용이 무엇을 뜻하는지 풀어 설명하므로 정의·명명이다."
    },
    {
      "id": "R35",
      "type": "CAUSE",
      "otherName": "",
      "reason": "내포 작용이 실제로 세포질 안의 엔도솜 형성을 일으키므로 인과·작용이다."
    },
    {
      "id": "R36",
      "type": "CAUSE",
      "otherName": "",
      "reason": "엔도솜 내부의 산성화가 엔도솜 막의 불안정화를 일으키므로 인과·작용이다."
    },
    {
      "id": "R37",
      "type": "CAUSE",
      "otherName": "",
      "reason": "엔도솜 막의 불안정화가 실제로 mRNA의 세포질 방출로 이어지므로 인과·작용이다."
    },
    {
      "id": "R38",
      "type": "PROCESS",
      "otherName": "",
      "reason": "mRNA의 세포질 방출 다음에 리보솜 결합과 단백질 합성 및 면역 반응이 이어지는 단계적 흐름이므로 과정·순서이다."
    },
    {
      "id": "R39",
      "type": "CAUSE",
      "otherName": "",
      "reason": "기억 세포의 생성이 인체의 바이러스 감염 대비 능력으로 이어지는 실제 작용이므로 인과·작용이다."
    },
    {
      "id": "R40",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "일반적인 mRNA와 리보솜의 단백질 합성 원리를 백신 mRNA의 작동에 가져다 쓰므로 원리 적용이다."
    },
    {
      "id": "R41",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "기억 세포로 바이러스 침입에 대비하는 일반 면역 원리를 mRNA 백신의 예방 효과에 적용하므로 원리 적용이다."
    },
    {
      "id": "R42",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "동일한 mRNA 백신의 면역 유도 방식을 리보솜 결합과 기억 세포 생성 과정으로 자세히 풀므로 구체화·예시이다."
    }
  ]
}

